insert into public.playbooks (slug, title, summary, department, industries, capabilities, trigger, steps, agent, estimated_minutes_per_occurrence, status)
values
  ('library-invoice-chasing', 'Invoice chasing', 'Reminds customers about overdue invoices on a fixed schedule and tells finance who still has not paid.', 'Finance', array['SaaS & software', 'Marketplaces', 'E-commerce & D2C', 'Media & publishing', 'Agencies', 'Recruitment & staffing', 'Online education', 'Property & rentals', 'Fintech & insurance', 'Professional services', 'Other']::text[], array['accounting', 'payments', 'email', 'chat']::text[], 'An invoice passes its due date unpaid', '[{"title":"Find invoices past their due date","detail":"List open invoices with a due date before today and no payment.","capability":"accounting","access":"read"},{"title":"Check for a payment that has not been matched yet","detail":"Look for a payment from the same customer for the same amount.","capability":"payments","access":"read"},{"title":"Pick the reminder for how late it is","detail":"Friendly at 3 days, firm at 14 days, final notice at 30 days.","capability":null,"access":"none"},{"title":"Send the reminder","detail":"Email the billing contact with the invoice number, amount and a payment link.","capability":"email","access":"write"},{"title":"Tell finance about invoices over 30 days late","detail":"Post a short list with customer, amount and days overdue.","capability":"chat","access":"write"}]'::jsonb, '{"name":"Invoice chasing","description":"Sends payment reminders for overdue invoices and escalates long-overdue ones.","autonomyLevel":3,"instructions":{"objective":"Get overdue invoices paid without anyone having to chase them by hand.","context":"Reminders go to the customer''s billing contact. Finance decides on anything beyond reminders.","rules":["Never send more than one reminder per invoice in 7 days","Never threaten collection or legal steps","Skip invoices that are disputed"],"steps":["Find invoices past their due date: List open invoices with a due date before today and no payment.","Check for a payment that has not been matched yet: Look for a payment from the same customer for the same amount.","Pick the reminder for how late it is: Friendly at 3 days, firm at 14 days, final notice at 30 days.","Send the reminder: Email the billing contact with the invoice number, amount and a payment link.","Tell finance about invoices over 30 days late: Post a short list with customer, amount and days overdue."],"escalationConditions":["The customer disputes the invoice","The invoice is over 60 days overdue","The amount is above the approval limit"],"successConditions":["Every overdue invoice got the right reminder","Finance knows about every invoice over 30 days late"]},"successCriteria":["Every overdue invoice got the right reminder","Finance knows about every invoice over 30 days late"]}'::jsonb, 10, 'published'),
  ('library-ticket-triage', 'Support ticket triage', 'Reads each new ticket, tags its topic and urgency, and routes it to the right queue with a suggested reply.', 'Customer Support', array['SaaS & software', 'Marketplaces', 'E-commerce & D2C', 'Media & publishing', 'Agencies', 'Recruitment & staffing', 'Online education', 'Travel & booking', 'Property & rentals', 'Fintech & insurance', 'Professional services', 'Other']::text[], array['helpdesk', 'crm']::text[], 'A new support ticket arrives', '[{"title":"Read the new ticket","detail":"Subject, message and any attachments.","capability":"helpdesk","access":"read"},{"title":"Look up the customer","detail":"Plan, account status and recent tickets.","capability":"crm","access":"read"},{"title":"Decide topic, urgency and queue","detail":"Billing, technical, account or other; urgent when a customer cannot work or pay.","capability":null,"access":"none"},{"title":"Tag and route the ticket","detail":"Set tags, priority and the queue or assignee.","capability":"helpdesk","access":"write"},{"title":"Add a suggested reply as an internal note","detail":"A draft the agent can send or edit.","capability":"helpdesk","access":"write"}]'::jsonb, '{"name":"Ticket triage","description":"Tags, prioritises and routes new support tickets with a draft reply.","autonomyLevel":4,"instructions":{"objective":"Every new ticket reaches the right person, correctly prioritised, within minutes.","context":"Routing rules and queue names come from the help desk.","rules":["Never reply to the customer directly","Mark anything about security or data loss as urgent"],"steps":["Read the new ticket: Subject, message and any attachments.","Look up the customer: Plan, account status and recent tickets.","Decide topic, urgency and queue: Billing, technical, account or other; urgent when a customer cannot work or pay.","Tag and route the ticket: Set tags, priority and the queue or assignee.","Add a suggested reply as an internal note: A draft the agent can send or edit."],"escalationConditions":["The ticket mentions a legal threat or a data breach","The topic fits no queue"],"successConditions":["Ticket tagged and routed","Draft reply added as an internal note"]},"successCriteria":["Ticket tagged and routed","Draft reply added as an internal note"]}'::jsonb, 4, 'published'),
  ('library-refund-requests', 'Refund and cancellation requests', 'Checks each refund or cancellation request against the policy and prepares the refund for approval.', 'Customer Support', array['E-commerce & D2C', 'SaaS & software', 'Travel & booking', 'Online education', 'Marketplaces', 'Media & publishing', 'Other']::text[], array['helpdesk', 'payments']::text[], 'A customer asks for a refund or to cancel', '[{"title":"Read the request","detail":"What is being refunded or cancelled, and why.","capability":"helpdesk","access":"read"},{"title":"Find the payment","detail":"The charge, its amount and date.","capability":"payments","access":"read"},{"title":"Check the refund policy","detail":"Within the refund window, eligible reason, not refunded before.","capability":null,"access":"none"},{"title":"Refund the payment","detail":"Full or partial refund as the policy allows. A person approves above the limit.","capability":"payments","access":"write"},{"title":"Reply and close the request","detail":"Confirm the refund amount and when it arrives.","capability":"helpdesk","access":"write"}]'::jsonb, '{"name":"Refund requests","description":"Handles refund and cancellation requests within the refund policy.","autonomyLevel":3,"instructions":{"objective":"Resolve eligible refund requests quickly and consistently with the policy.","context":"The refund policy sets the window and eligible reasons.","rules":["Never refund more than the original charge","Never refund a payment twice","Refunds above the approval limit wait for a person"],"steps":["Read the request: What is being refunded or cancelled, and why.","Find the payment: The charge, its amount and date.","Check the refund policy: Within the refund window, eligible reason, not refunded before.","Refund the payment: Full or partial refund as the policy allows. A person approves above the limit.","Reply and close the request: Confirm the refund amount and when it arrives."],"escalationConditions":["The request is outside the refund window","The customer has had more than two refunds this year","Fraud is suspected"],"successConditions":["Eligible requests refunded and answered","Ineligible requests explained with the policy"]},"successCriteria":["Eligible requests refunded and answered","Ineligible requests explained with the policy"]}'::jsonb, 8, 'published'),
  ('library-lead-routing', 'Inbound lead qualification', 'Qualifies each new inbound lead, enriches it, and routes it to the right owner the same day.', 'Sales', array['SaaS & software', 'Agencies', 'Professional services', 'Property & rentals', 'Recruitment & staffing', 'Other']::text[], array['crm', 'chat']::text[], 'A new lead fills in a form or emails in', '[{"title":"Read the new lead","detail":"Name, company, message and source.","capability":"crm","access":"read"},{"title":"Check for an existing account or open deal","detail":"Avoid duplicates and route to the current owner.","capability":"crm","access":"read"},{"title":"Score fit and intent","detail":"Company size, need, budget signals and urgency.","capability":null,"access":"none"},{"title":"Assign an owner and set the stage","detail":"By territory or segment; qualified leads become a deal.","capability":"crm","access":"write"},{"title":"Tell the owner","detail":"Short summary with why the lead looks good.","capability":"chat","access":"write"}]'::jsonb, '{"name":"Lead qualification","description":"Qualifies and routes inbound leads to the right owner.","autonomyLevel":4,"instructions":{"objective":"No good lead waits more than a few hours for an owner.","context":"Owners are assigned by territory or segment in the CRM.","rules":["Never email the lead","Never change an existing deal''s owner"],"steps":["Read the new lead: Name, company, message and source.","Check for an existing account or open deal: Avoid duplicates and route to the current owner.","Score fit and intent: Company size, need, budget signals and urgency.","Assign an owner and set the stage: By territory or segment; qualified leads become a deal.","Tell the owner: Short summary with why the lead looks good."],"escalationConditions":["The lead is a large company or partner","The message is a complaint, not a sales enquiry"],"successConditions":["Every lead has an owner and a stage","The owner was told the same day"]},"successCriteria":["Every lead has an owner and a stage","The owner was told the same day"]}'::jsonb, 12, 'published'),
  ('library-customer-onboarding', 'New customer onboarding', 'Welcomes each new customer, checks setup steps are done, and nudges or flags the ones who stall.', 'Customer Support', array['SaaS & software', 'Fintech & insurance', 'Online education', 'Agencies', 'Other']::text[], array['crm', 'email', 'calendar', 'chat']::text[], 'A new customer signs up or signs the contract', '[{"title":"Get the new customer''s details","detail":"Plan, contact person and start date.","capability":"crm","access":"read"},{"title":"Send the welcome email","detail":"With the first steps and how to get help.","capability":"email","access":"write"},{"title":"Book the kickoff call","detail":"Offer times that suit the account owner.","capability":"calendar","access":"write"},{"title":"Check setup progress after a week","detail":"Which onboarding steps are done.","capability":"crm","access":"read"},{"title":"Nudge or flag stalled customers","detail":"A helpful reminder, or a note to the account owner.","capability":"chat","access":"write"}]'::jsonb, '{"name":"Customer onboarding","description":"Guides new customers through their first weeks.","autonomyLevel":3,"instructions":{"objective":"Every new customer completes setup in their first two weeks.","context":"The onboarding checklist lives in the CRM.","rules":["At most one nudge email per week","Never promise features or discounts"],"steps":["Get the new customer''s details: Plan, contact person and start date.","Send the welcome email: With the first steps and how to get help.","Book the kickoff call: Offer times that suit the account owner.","Check setup progress after a week: Which onboarding steps are done.","Nudge or flag stalled customers: A helpful reminder, or a note to the account owner."],"escalationConditions":["The customer is unhappy or asks to cancel","No progress after two nudges"],"successConditions":["Welcome sent and kickoff booked","Stalled customers flagged to their owner"]},"successCriteria":["Welcome sent and kickoff booked","Stalled customers flagged to their owner"]}'::jsonb, 15, 'published'),
  ('library-document-chasing', 'Document chasing', 'Collects missing documents (contracts, certificates, ID checks) with polite reminders until the file is complete.', 'Operations', array['Fintech & insurance', 'Recruitment & staffing', 'Property & rentals', 'Professional services', 'Other']::text[], array['documents', 'email', 'chat']::text[], 'A file is missing a required document', '[{"title":"List files with missing documents","detail":"Which documents each file still needs.","capability":"documents","access":"read"},{"title":"Request the missing documents","detail":"Email listing exactly what is needed and how to send it.","capability":"email","access":"write"},{"title":"Check what came back","detail":"Match received documents to the file.","capability":"documents","access":"read"},{"title":"File the documents and update the checklist","detail":"Mark each item received.","capability":"documents","access":"write"},{"title":"Flag files still incomplete after two reminders","detail":"To the person responsible.","capability":"chat","access":"write"}]'::jsonb, '{"name":"Document chasing","description":"Requests and files missing documents until each file is complete.","autonomyLevel":3,"instructions":{"objective":"Complete files without anyone chasing documents by hand.","context":"Back-office only: the agent collects and files documents, a person reviews their content.","rules":["Never judge whether a document is valid","Never ask for documents the checklist does not require","At most two reminders a week"],"steps":["List files with missing documents: Which documents each file still needs.","Request the missing documents: Email listing exactly what is needed and how to send it.","Check what came back: Match received documents to the file.","File the documents and update the checklist: Mark each item received.","Flag files still incomplete after two reminders: To the person responsible."],"escalationConditions":["A document looks altered or does not match the person","The person refuses or asks why"],"successConditions":["Requested documents filed","Incomplete files flagged after two reminders"]},"successCriteria":["Requested documents filed","Incomplete files flagged after two reminders"]}'::jsonb, 10, 'published'),
  ('library-failed-payment-recovery', 'Failed payment recovery', 'Follows up failed card payments with clear, timed reminders until the payment method is updated.', 'Finance', array['SaaS & software', 'Media & publishing', 'Fintech & insurance', 'Online education']::text[], array['payments', 'email', 'chat']::text[], 'A recurring payment fails', '[{"title":"Read the failed payment","detail":"Customer, amount and why it failed.","capability":"payments","access":"read"},{"title":"Email the customer to update their card","detail":"With a secure update link.","capability":"email","access":"write"},{"title":"Check whether the retry succeeded","detail":"After the next scheduled retry.","capability":"payments","access":"read"},{"title":"Send a final notice before the subscription pauses","detail":"Clear date and what happens next.","capability":"email","access":"write"},{"title":"Tell the account owner about high-value accounts","detail":"Before access is lost.","capability":"chat","access":"write"}]'::jsonb, '{"name":"Payment recovery","description":"Recovers failed recurring payments with timed reminders.","autonomyLevel":4,"instructions":{"objective":"Recover failed payments before customers lose access.","context":"Payment retries are scheduled by the payment system.","rules":["Never charge the card manually","Never change the subscription"],"steps":["Read the failed payment: Customer, amount and why it failed.","Email the customer to update their card: With a secure update link.","Check whether the retry succeeded: After the next scheduled retry.","Send a final notice before the subscription pauses: Clear date and what happens next.","Tell the account owner about high-value accounts: Before access is lost."],"escalationConditions":["The customer replies with a complaint","The account pays above the high-value threshold"],"successConditions":["Customer told within a day of the failure","High-value accounts flagged"]},"successCriteria":["Customer told within a day of the failure","High-value accounts flagged"]}'::jsonb, 6, 'published'),
  ('library-trial-follow-up', 'Trial-to-paid follow-up', 'Follows up trial users based on how much they used the product, and flags the hottest trials to sales.', 'Sales', array['SaaS & software']::text[], array['crm', 'email']::text[], 'A trial is three days from ending', '[{"title":"List trials ending soon","detail":"Trial end date, plan and contact.","capability":"crm","access":"read"},{"title":"Group trials by activity","detail":"Active, light use, or no use.","capability":null,"access":"none"},{"title":"Send the matching follow-up","detail":"Tips for light users, an offer to help for active ones.","capability":"email","access":"write"},{"title":"Hand the most active trials to sales","detail":"With what they used most.","capability":"crm","access":"write"}]'::jsonb, '{"name":"Trial follow-up","description":"Converts trials with timely, relevant follow-ups.","autonomyLevel":3,"instructions":{"objective":"More trials become paying customers.","context":"Activity comes from what the CRM records for the trial.","rules":["Never offer discounts","One email per trial per stage"],"steps":["List trials ending soon: Trial end date, plan and contact.","Group trials by activity: Active, light use, or no use.","Send the matching follow-up: Tips for light users, an offer to help for active ones.","Hand the most active trials to sales: With what they used most."],"escalationConditions":["The trial is a large company","The user asks about pricing for many seats"],"successConditions":["Every ending trial got a follow-up","Active trials handed to sales"]},"successCriteria":["Every ending trial got a follow-up","Active trials handed to sales"]}'::jsonb, 8, 'published'),
  ('library-churn-risk-outreach', 'Churn-risk outreach', 'Spots customers showing signs of leaving and gets their account owner in touch before renewal.', 'Customer Support', array['SaaS & software']::text[], array['crm', 'helpdesk', 'projects']::text[], 'Every Monday', '[{"title":"Find accounts with churn signals","detail":"Falling use, open complaints, renewal within 60 days.","capability":"crm","access":"read"},{"title":"Check open tickets for each account","detail":"Unresolved problems and tone.","capability":"helpdesk","access":"read"},{"title":"Rank the accounts at risk","detail":"By revenue and how strong the signals are.","capability":null,"access":"none"},{"title":"Create a save task for the owner","detail":"With the signals and a suggested next step.","capability":"projects","access":"write"}]'::jsonb, '{"name":"Churn risk","description":"Finds at-risk accounts each week and sets up save tasks.","autonomyLevel":3,"instructions":{"objective":"No renewal is lost without the owner knowing in time.","context":"Signals come from the CRM and help desk.","rules":["Never contact the customer","Never change the renewal or price"],"steps":["Find accounts with churn signals: Falling use, open complaints, renewal within 60 days.","Check open tickets for each account: Unresolved problems and tone.","Rank the accounts at risk: By revenue and how strong the signals are.","Create a save task for the owner: With the signals and a suggested next step."],"escalationConditions":["One of the largest accounts shows strong signals"],"successConditions":["Save tasks created for every at-risk account"]},"successCriteria":["Save tasks created for every at-risk account"]}'::jsonb, 20, 'published'),
  ('library-listing-moderation', 'New listing moderation', 'Checks every new listing against the listing rules and approves, fixes or holds it for review.', 'Operations', array['Marketplaces', 'Property & rentals']::text[], array['ecommerce', 'email']::text[], 'A seller publishes a new listing', '[{"title":"Read the new listing","detail":"Title, description, photos and price.","capability":"ecommerce","access":"read"},{"title":"Check it against the listing rules","detail":"Prohibited items, misleading claims, contact details in text, price far off.","capability":null,"access":"none"},{"title":"Approve or hold the listing","detail":"Clear listings go live; others wait for review.","capability":"ecommerce","access":"write"},{"title":"Tell the seller what to fix","detail":"When a listing is held.","capability":"email","access":"write"}]'::jsonb, '{"name":"Listing moderation","description":"Moderates new listings against the listing rules.","autonomyLevel":3,"instructions":{"objective":"Only listings that meet the rules go live, without slowing honest sellers down.","context":"The listing rules list prohibited items and required fields.","rules":["Never delete a listing","Hold, do not reject, when unsure"],"steps":["Read the new listing: Title, description, photos and price.","Check it against the listing rules: Prohibited items, misleading claims, contact details in text, price far off.","Approve or hold the listing: Clear listings go live; others wait for review.","Tell the seller what to fix: When a listing is held."],"escalationConditions":["The listing may involve illegal items or animal welfare","The seller has had listings held before"],"successConditions":["Every new listing approved or held within minutes"]},"successCriteria":["Every new listing approved or held within minutes"]}'::jsonb, 3, 'published'),
  ('library-seller-onboarding', 'Seller onboarding and verification', 'Walks new sellers through verification and their first listing, and flags sellers who stall.', 'Operations', array['Marketplaces']::text[], array['crm', 'email', 'chat']::text[], 'A new seller signs up', '[{"title":"Read the new seller''s account","detail":"Business details and verification status.","capability":"crm","access":"read"},{"title":"Send the welcome and verification steps","detail":"What is needed to start selling.","capability":"email","access":"write"},{"title":"Check verification after three days","detail":"Documents and payout details received.","capability":"crm","access":"read"},{"title":"Remind sellers who have not finished","detail":"One friendly reminder.","capability":"email","access":"write"},{"title":"Flag sellers stuck after the reminder","detail":"To the seller team.","capability":"chat","access":"write"}]'::jsonb, '{"name":"Seller onboarding","description":"Gets new sellers verified and listing.","autonomyLevel":3,"instructions":{"objective":"New sellers finish verification and publish their first listing within a week.","context":"Verification decisions are made by the seller team.","rules":["Never approve verification","Never ask for documents beyond the checklist"],"steps":["Read the new seller''s account: Business details and verification status.","Send the welcome and verification steps: What is needed to start selling.","Check verification after three days: Documents and payout details received.","Remind sellers who have not finished: One friendly reminder.","Flag sellers stuck after the reminder: To the seller team."],"escalationConditions":["Details do not match","The seller is a large business"],"successConditions":["Every new seller welcomed and reminded once"]},"successCriteria":["Every new seller welcomed and reminded once"]}'::jsonb, 12, 'published'),
  ('library-dispute-handling', 'Buyer and seller dispute handling', 'Gathers both sides of a dispute, the order and messages, and proposes an outcome for a person to approve.', 'Customer Support', array['Marketplaces', 'Travel & booking', 'E-commerce & D2C']::text[], array['helpdesk', 'payments', 'email']::text[], 'A buyer or seller opens a dispute', '[{"title":"Read the dispute","detail":"Who opened it, why, and what they want.","capability":"helpdesk","access":"read"},{"title":"Get the order and payment","detail":"Amount, dates and delivery status.","capability":"payments","access":"read"},{"title":"Ask the other side for their account","detail":"A neutral request with a deadline.","capability":"email","access":"write"},{"title":"Propose an outcome under the dispute policy","detail":"Refund, partial refund or no action, with reasons.","capability":null,"access":"none"},{"title":"Send the outcome once approved","detail":"To both sides.","capability":"helpdesk","access":"write"}]'::jsonb, '{"name":"Dispute handling","description":"Prepares disputes for a fair, fast decision.","autonomyLevel":2,"instructions":{"objective":"Disputes are decided fairly and quickly with all the facts in one place.","context":"A person approves every outcome.","rules":["Stay neutral in every message","Never move money without approval"],"steps":["Read the dispute: Who opened it, why, and what they want.","Get the order and payment: Amount, dates and delivery status.","Ask the other side for their account: A neutral request with a deadline.","Propose an outcome under the dispute policy: Refund, partial refund or no action, with reasons.","Send the outcome once approved: To both sides."],"escalationConditions":["Either side threatens legal action","The amount is above the approval limit"],"successConditions":["Both sides heard","Outcome proposed with reasons"]},"successCriteria":["Both sides heard","Outcome proposed with reasons"]}'::jsonb, 20, 'published'),
  ('library-order-status', 'Where-is-my-order replies', 'Answers order status questions with live tracking and handles late deliveries before customers ask twice.', 'Customer Support', array['E-commerce & D2C']::text[], array['helpdesk', 'ecommerce']::text[], 'A customer asks where their order is', '[{"title":"Read the question","detail":"Order number or the customer''s email.","capability":"helpdesk","access":"read"},{"title":"Look up the order and shipment","detail":"Status, carrier and tracking.","capability":"ecommerce","access":"read"},{"title":"Is the order late?","detail":"Compare with the promised delivery date.","capability":null,"access":"none"},{"title":"Reply with the status and tracking link","detail":"Apologise and say what happens next if it is late.","capability":"helpdesk","access":"write"}]'::jsonb, '{"name":"Order status","description":"Answers where-is-my-order questions with live tracking.","autonomyLevel":4,"instructions":{"objective":"Customers get an accurate order status within minutes.","context":"Delivery promises are shown on the order.","rules":["Never promise a delivery date the carrier has not given","Never offer compensation"],"steps":["Read the question: Order number or the customer''s email.","Look up the order and shipment: Status, carrier and tracking.","Is the order late?: Compare with the promised delivery date.","Reply with the status and tracking link: Apologise and say what happens next if it is late."],"escalationConditions":["The order is more than 5 days late","The parcel is marked delivered but the customer says it is not"],"successConditions":["Question answered with the current status"]},"successCriteria":["Question answered with the current status"]}'::jsonb, 5, 'published'),
  ('library-returns', 'Returns and exchanges', 'Approves returns within the return policy, sends the return label and tracks it back.', 'Customer Support', array['E-commerce & D2C']::text[], array['helpdesk', 'ecommerce', 'email']::text[], 'A customer asks to return or exchange an item', '[{"title":"Read the return request","detail":"Item, reason and whether they want a refund or exchange.","capability":"helpdesk","access":"read"},{"title":"Check the order","detail":"Purchase date and item condition rules.","capability":"ecommerce","access":"read"},{"title":"Check the return policy","detail":"Within the return window, item returnable.","capability":null,"access":"none"},{"title":"Send the return instructions","detail":"Label or address and what to include.","capability":"email","access":"write"},{"title":"Update the order","detail":"Mark a return as expected.","capability":"ecommerce","access":"write"}]'::jsonb, '{"name":"Returns","description":"Handles returns and exchanges within the return policy.","autonomyLevel":3,"instructions":{"objective":"Eligible returns are approved the same day.","context":"Refunds happen when the return arrives, not before.","rules":["Never refund before the item is back","Final-sale items cannot be returned"],"steps":["Read the return request: Item, reason and whether they want a refund or exchange.","Check the order: Purchase date and item condition rules.","Check the return policy: Within the return window, item returnable.","Send the return instructions: Label or address and what to include.","Update the order: Mark a return as expected."],"escalationConditions":["The item is damaged or faulty","The customer has many returns"],"successConditions":["Instructions sent","Order marked as return expected"]},"successCriteria":["Instructions sent","Order marked as return expected"]}'::jsonb, 8, 'published'),
  ('library-low-stock', 'Low-stock reorder alerts', 'Watches stock levels and drafts a reorder for products about to run out.', 'Operations', array['E-commerce & D2C']::text[], array['ecommerce', 'spreadsheet', 'chat']::text[], 'Every morning', '[{"title":"Check stock levels","detail":"Products below their reorder point.","capability":"ecommerce","access":"read"},{"title":"Work out the reorder quantity","detail":"From the last 30 days of sales.","capability":null,"access":"none"},{"title":"Draft the reorder","detail":"Quantity per product in the purchasing sheet.","capability":"spreadsheet","access":"write"},{"title":"Tell the buyer","detail":"List of products and quantities to approve.","capability":"chat","access":"write"}]'::jsonb, '{"name":"Low-stock alerts","description":"Spots products running low and drafts reorders.","autonomyLevel":2,"instructions":{"objective":"Best-sellers never go out of stock.","context":"Purchase orders are placed by a person.","rules":["Never place an order","Skip discontinued products"],"steps":["Check stock levels: Products below their reorder point.","Work out the reorder quantity: From the last 30 days of sales.","Draft the reorder: Quantity per product in the purchasing sheet.","Tell the buyer: List of products and quantities to approve."],"escalationConditions":["A best-seller will run out within 3 days"],"successConditions":["Reorder drafted for every product below its reorder point"]},"successCriteria":["Reorder drafted for every product below its reorder point"]}'::jsonb, 15, 'published'),
  ('library-subscriber-save', 'Subscriber cancellation save', 'Answers cancellation requests with the right retention offer, and cancels cleanly when the reader still wants to go.', 'Customer Support', array['Media & publishing']::text[], array['helpdesk', 'payments']::text[], 'A subscriber asks to cancel', '[{"title":"Read the cancellation request","detail":"Reason if given.","capability":"helpdesk","access":"read"},{"title":"Look up the subscription","detail":"Plan, tenure and price.","capability":"payments","access":"read"},{"title":"Pick the retention option","detail":"A pause, a cheaper plan, or none, by the retention rules.","capability":null,"access":"none"},{"title":"Reply with the option or confirm the cancellation","detail":"Always make cancelling easy.","capability":"helpdesk","access":"write"}]'::jsonb, '{"name":"Subscriber retention","description":"Handles cancellations fairly, with a retention offer where the rules allow.","autonomyLevel":3,"instructions":{"objective":"Keep subscribers who would stay with a better option, and let others go without friction.","context":"Retention offers are set by the retention rules.","rules":["Never refuse or delay a cancellation","One offer only"],"steps":["Read the cancellation request: Reason if given.","Look up the subscription: Plan, tenure and price.","Pick the retention option: A pause, a cheaper plan, or none, by the retention rules.","Reply with the option or confirm the cancellation: Always make cancelling easy."],"escalationConditions":["The subscriber is angry or mentions a complaint"],"successConditions":["Every request answered the same day"]},"successCriteria":["Every request answered the same day"]}'::jsonb, 6, 'published'),
  ('library-comment-moderation', 'Comment and content moderation', 'Reviews reader comments and submissions against the community rules and holds the ones that break them.', 'Operations', array['Media & publishing', 'Marketplaces']::text[], array['documents', 'chat']::text[], 'A new comment or submission is posted', '[{"title":"Read the comment","detail":"Text and the article it is on.","capability":"documents","access":"read"},{"title":"Check it against the community rules","detail":"Abuse, spam, personal data, off-topic.","capability":null,"access":"none"},{"title":"Publish or hold the comment","detail":"Hold, do not delete, when unsure.","capability":"documents","access":"write"},{"title":"Report repeat offenders","detail":"To the community editor.","capability":"chat","access":"write"}]'::jsonb, '{"name":"Comment moderation","description":"Moderates comments against the community rules.","autonomyLevel":4,"instructions":{"objective":"Conversations stay civil without slowing them down.","context":"Editors make final decisions on held comments.","rules":["Never edit a reader''s words","Never ban accounts"],"steps":["Read the comment: Text and the article it is on.","Check it against the community rules: Abuse, spam, personal data, off-topic.","Publish or hold the comment: Hold, do not delete, when unsure.","Report repeat offenders: To the community editor."],"escalationConditions":["A comment contains threats or personal data","Legal risk such as defamation"],"successConditions":["Every comment published or held within minutes"]},"successCriteria":["Every comment published or held within minutes"]}'::jsonb, 2, 'published'),
  ('library-advertiser-booking', 'Advertiser booking and invoicing', 'Turns confirmed ad bookings into scheduled placements and invoices, and chases missing creative.', 'Sales', array['Media & publishing']::text[], array['crm', 'spreadsheet', 'email', 'accounting']::text[], 'An advertiser confirms a booking', '[{"title":"Read the confirmed booking","detail":"Placements, dates and price.","capability":"crm","access":"read"},{"title":"Schedule the placements","detail":"In the ad planning sheet.","capability":"spreadsheet","access":"write"},{"title":"Ask for missing creative","detail":"With the specs and deadline.","capability":"email","access":"write"},{"title":"Create the invoice","detail":"For the agreed price and payment terms.","capability":"accounting","access":"write"}]'::jsonb, '{"name":"Ad bookings","description":"Schedules ad bookings, chases creative and invoices them.","autonomyLevel":3,"instructions":{"objective":"Every confirmed booking runs on time and is invoiced.","context":"Prices come from the booking, never from the agent.","rules":["Never change prices or dates","Invoices above the approval limit wait for a person"],"steps":["Read the confirmed booking: Placements, dates and price.","Schedule the placements: In the ad planning sheet.","Ask for missing creative: With the specs and deadline.","Create the invoice: For the agreed price and payment terms."],"escalationConditions":["Creative is still missing two days before the run"],"successConditions":["Placements scheduled","Invoice created"]},"successCriteria":["Placements scheduled","Invoice created"]}'::jsonb, 15, 'published'),
  ('library-client-report', 'Weekly client performance report', 'Pulls each client''s campaign numbers into a short weekly report for the account lead to send.', 'Marketing', array['Agencies']::text[], array['marketing', 'spreadsheet', 'documents', 'chat']::text[], 'Every Friday', '[{"title":"Collect the week''s campaign results","detail":"Spend, results and cost per result per client.","capability":"marketing","access":"read"},{"title":"Compare with last week and the target","detail":"From the client tracker.","capability":"spreadsheet","access":"read"},{"title":"Write the three things that matter","detail":"What changed, why, and what to do next.","capability":null,"access":"none"},{"title":"Draft the report","detail":"One page per client.","capability":"documents","access":"write"},{"title":"Tell the account lead it is ready","detail":"With the link.","capability":"chat","access":"write"}]'::jsonb, '{"name":"Client reports","description":"Drafts weekly performance reports for each client.","autonomyLevel":2,"instructions":{"objective":"Account leads spend minutes, not hours, on weekly reports.","context":"The account lead reviews and sends every report.","rules":["Never send to the client","Only use numbers from the data"],"steps":["Collect the week''s campaign results: Spend, results and cost per result per client.","Compare with last week and the target: From the client tracker.","Write the three things that matter: What changed, why, and what to do next.","Draft the report: One page per client.","Tell the account lead it is ready: With the link."],"escalationConditions":["Results are far below target"],"successConditions":["A draft report for every client by Friday afternoon"]},"successCriteria":["A draft report for every client by Friday afternoon"]}'::jsonb, 45, 'published'),
  ('library-timesheet-reminders', 'Timesheet reminders', 'Reminds people with missing hours before the week closes and tells the manager who is still missing.', 'Operations', array['Agencies', 'Professional services', 'Recruitment & staffing']::text[], array['projects', 'chat']::text[], 'Every Friday afternoon', '[{"title":"Find missing or short timesheets","detail":"Hours logged against expected hours.","capability":"projects","access":"read"},{"title":"Remind each person","detail":"Short, friendly message with their missing days.","capability":"chat","access":"write"},{"title":"Check again on Monday morning","detail":"Who has still not filled in.","capability":"projects","access":"read"},{"title":"Tell the manager who is missing","detail":"So invoicing is not delayed.","capability":"chat","access":"write"}]'::jsonb, '{"name":"Timesheet reminders","description":"Makes sure hours are logged before invoicing.","autonomyLevel":4,"instructions":{"objective":"All hours are in before the invoicing run.","context":"Expected hours come from contracts in the project tool.","rules":["Never fill in hours for someone"],"steps":["Find missing or short timesheets: Hours logged against expected hours.","Remind each person: Short, friendly message with their missing days.","Check again on Monday morning: Who has still not filled in.","Tell the manager who is missing: So invoicing is not delayed."],"escalationConditions":["Someone is missing a whole week"],"successConditions":["Everyone reminded","Manager told about anyone still missing"]},"successCriteria":["Everyone reminded","Manager told about anyone still missing"]}'::jsonb, 20, 'published'),
  ('library-project-kickoff', 'Project kickoff from a signed proposal', 'Turns a signed proposal into a project with tasks, a kickoff meeting and a client welcome.', 'Operations', array['Agencies', 'Professional services']::text[], array['esign', 'projects', 'calendar', 'email']::text[], 'A proposal is signed', '[{"title":"Read the signed proposal","detail":"Scope, deliverables, dates and team.","capability":"esign","access":"read"},{"title":"Create the project and tasks","detail":"From the scope and deliverables.","capability":"projects","access":"write"},{"title":"Book the kickoff meeting","detail":"With the client and the team.","capability":"calendar","access":"write"},{"title":"Send the client welcome","detail":"What happens next and who their contacts are.","capability":"email","access":"write"}]'::jsonb, '{"name":"Project kickoff","description":"Sets up new projects as soon as the proposal is signed.","autonomyLevel":3,"instructions":{"objective":"Work starts the week the proposal is signed.","context":"The scope in the proposal is the source of truth.","rules":["Never add scope beyond the proposal"],"steps":["Read the signed proposal: Scope, deliverables, dates and team.","Create the project and tasks: From the scope and deliverables.","Book the kickoff meeting: With the client and the team.","Send the client welcome: What happens next and who their contacts are."],"escalationConditions":["Dates in the proposal have already passed"],"successConditions":["Project created","Kickoff booked","Client welcomed"]},"successCriteria":["Project created","Kickoff booked","Client welcomed"]}'::jsonb, 30, 'published'),
  ('library-candidate-screening', 'Candidate screening and interview scheduling', 'Screens new applicants against the must-haves and books interviews for the ones who fit.', 'HR', array['Recruitment & staffing']::text[], array['hr', 'calendar']::text[], 'A new application arrives', '[{"title":"Read the application","detail":"CV, cover letter and answers.","capability":"hr","access":"read"},{"title":"Check the must-have requirements","detail":"Only the requirements in the vacancy, never personal traits.","capability":null,"access":"none"},{"title":"Book interviews for candidates who fit","detail":"Offer slots from the recruiter''s calendar.","capability":"calendar","access":"write"},{"title":"Mark the rest for recruiter review","detail":"With the requirement that was not met.","capability":"hr","access":"write"}]'::jsonb, '{"name":"Candidate screening","description":"Screens applicants on the vacancy''s must-haves and books interviews.","autonomyLevel":3,"instructions":{"objective":"Good candidates get an interview within a day.","context":"Back-office only: a recruiter makes every rejection decision.","rules":["Never reject a candidate","Judge only on the vacancy''s stated requirements","Ignore age, gender, origin and other protected traits"],"steps":["Read the application: CV, cover letter and answers.","Check the must-have requirements: Only the requirements in the vacancy, never personal traits.","Book interviews for candidates who fit: Offer slots from the recruiter''s calendar.","Mark the rest for recruiter review: With the requirement that was not met."],"escalationConditions":["The vacancy has no clear must-haves"],"successConditions":["Interviews booked for candidates who fit","Others queued for a recruiter"]},"successCriteria":["Interviews booked for candidates who fit","Others queued for a recruiter"]}'::jsonb, 15, 'published'),
  ('library-contractor-timesheets', 'Contractor timesheet approval and invoicing', 'Collects approved contractor hours each week and drafts the client invoices from them.', 'Finance', array['Recruitment & staffing', 'Agencies']::text[], array['spreadsheet', 'email', 'accounting']::text[], 'Every Monday', '[{"title":"Collect last week''s timesheets","detail":"Hours per contractor and client.","capability":"spreadsheet","access":"read"},{"title":"Ask clients to approve open timesheets","detail":"With the hours to approve.","capability":"email","access":"write"},{"title":"Check which timesheets are approved","detail":"By Wednesday.","capability":"spreadsheet","access":"read"},{"title":"Draft invoices for approved hours","detail":"At the agreed rates.","capability":"accounting","access":"write"}]'::jsonb, '{"name":"Contractor invoicing","description":"Turns approved contractor hours into client invoices.","autonomyLevel":3,"instructions":{"objective":"Every approved hour is invoiced the same week.","context":"Rates come from the client agreement.","rules":["Never invoice unapproved hours","Never change rates"],"steps":["Collect last week''s timesheets: Hours per contractor and client.","Ask clients to approve open timesheets: With the hours to approve.","Check which timesheets are approved: By Wednesday.","Draft invoices for approved hours: At the agreed rates."],"escalationConditions":["A client disputes hours"],"successConditions":["Invoices drafted for all approved hours"]},"successCriteria":["Invoices drafted for all approved hours"]}'::jsonb, 30, 'published'),
  ('library-enrolment', 'Enrolment and payment-plan setup', 'Confirms new enrolments, sets up the payment plan and gives students their course access.', 'Operations', array['Online education']::text[], array['forms', 'payments', 'email', 'spreadsheet']::text[], 'A student enrols', '[{"title":"Read the enrolment","detail":"Course, start date and payment choice.","capability":"forms","access":"read"},{"title":"Set up the payment plan","detail":"Instalments as chosen.","capability":"payments","access":"write"},{"title":"Send the welcome and access details","detail":"Start date and how to log in.","capability":"email","access":"write"},{"title":"Add the student to the course list","detail":"For the course team.","capability":"spreadsheet","access":"write"}]'::jsonb, '{"name":"Enrolment","description":"Completes new enrolments end to end.","autonomyLevel":3,"instructions":{"objective":"Students have access and a payment plan within an hour of enrolling.","context":"Payment plan options are set per course.","rules":["Never offer discounts or extra instalments"],"steps":["Read the enrolment: Course, start date and payment choice.","Set up the payment plan: Instalments as chosen.","Send the welcome and access details: Start date and how to log in.","Add the student to the course list: For the course team."],"escalationConditions":["The course is full","The payment setup fails"],"successConditions":["Payment plan set up","Welcome sent"]},"successCriteria":["Payment plan set up","Welcome sent"]}'::jsonb, 10, 'published'),
  ('library-student-support', 'Student support answers', 'Answers common student questions from the course handbook and routes the rest to tutors.', 'Customer Support', array['Online education']::text[], array['helpdesk', 'documents']::text[], 'A student sends a question', '[{"title":"Read the question","detail":"And the student''s course.","capability":"helpdesk","access":"read"},{"title":"Search the course handbook","detail":"Deadlines, rules and how-tos.","capability":"documents","access":"read"},{"title":"Can the handbook answer it?","detail":"Only answer what the handbook covers.","capability":null,"access":"none"},{"title":"Reply or route to a tutor","detail":"Quote the handbook section when answering.","capability":"helpdesk","access":"write"}]'::jsonb, '{"name":"Student support","description":"Answers handbook questions and routes the rest.","autonomyLevel":4,"instructions":{"objective":"Students get answers to routine questions in minutes.","context":"Tutors handle anything about grades or course content.","rules":["Never comment on grades","Never grant extensions"],"steps":["Read the question: And the student''s course.","Search the course handbook: Deadlines, rules and how-tos.","Can the handbook answer it?: Only answer what the handbook covers.","Reply or route to a tutor: Quote the handbook section when answering."],"escalationConditions":["The student mentions wellbeing or a personal crisis"],"successConditions":["Routine questions answered","Others routed to a tutor"]},"successCriteria":["Routine questions answered","Others routed to a tutor"]}'::jsonb, 5, 'published'),
  ('library-certificates', 'Completion certificates', 'Issues certificates to students who completed their course and sends them by email.', 'Operations', array['Online education']::text[], array['spreadsheet', 'documents', 'email']::text[], 'Every evening', '[{"title":"Find students who completed a course today","detail":"From the course records.","capability":"spreadsheet","access":"read"},{"title":"Create each certificate","detail":"From the certificate template.","capability":"documents","access":"write"},{"title":"Email the certificate","detail":"With congratulations and the next course.","capability":"email","access":"write"}]'::jsonb, '{"name":"Certificates","description":"Issues completion certificates the day students finish.","autonomyLevel":4,"instructions":{"objective":"Every student who completes a course gets their certificate the same day.","context":"Completion is recorded by the course team.","rules":["Only issue for completions in the records"],"steps":["Find students who completed a course today: From the course records.","Create each certificate: From the certificate template.","Email the certificate: With congratulations and the next course."],"escalationConditions":["A student''s name is missing or unclear"],"successConditions":["Certificates created and sent"]},"successCriteria":["Certificates created and sent"]}'::jsonb, 5, 'published'),
  ('library-booking-changes', 'Booking change requests', 'Handles date and name changes within the change rules and quotes any fee before changing.', 'Customer Support', array['Travel & booking']::text[], array['helpdesk', 'ecommerce']::text[], 'A customer asks to change a booking', '[{"title":"Read the change request","detail":"What they want changed.","capability":"helpdesk","access":"read"},{"title":"Look up the booking","detail":"Dates, fare rules and supplier.","capability":"ecommerce","access":"read"},{"title":"Check the change rules","detail":"Allowed changes and the fee.","capability":null,"access":"none"},{"title":"Quote the change and fee","detail":"Ask the customer to confirm.","capability":"helpdesk","access":"write"},{"title":"Make the change once confirmed","detail":"And send the updated confirmation.","capability":"ecommerce","access":"write"}]'::jsonb, '{"name":"Booking changes","description":"Handles booking changes within the change rules.","autonomyLevel":3,"instructions":{"objective":"Routine changes are done in one exchange.","context":"Supplier rules decide what can change.","rules":["Never change a booking before the customer confirms the fee","Never waive fees"],"steps":["Read the change request: What they want changed.","Look up the booking: Dates, fare rules and supplier.","Check the change rules: Allowed changes and the fee.","Quote the change and fee: Ask the customer to confirm.","Make the change once confirmed: And send the updated confirmation."],"escalationConditions":["The supplier does not allow the change","The trip starts within 48 hours"],"successConditions":["Change quoted and, once confirmed, made"]},"successCriteria":["Change quoted and, once confirmed, made"]}'::jsonb, 10, 'published'),
  ('library-supplier-reconciliation', 'Supplier invoice reconciliation', 'Matches supplier invoices to bookings and flags mismatches before they are paid.', 'Finance', array['Travel & booking', 'E-commerce & D2C']::text[], array['accounting', 'spreadsheet']::text[], 'A supplier invoice arrives', '[{"title":"Read the supplier invoice","detail":"Lines, amounts and references.","capability":"accounting","access":"read"},{"title":"Find the matching bookings or orders","detail":"By reference and date.","capability":"spreadsheet","access":"read"},{"title":"Compare amounts and quantities","detail":"Flag any difference above the tolerance.","capability":null,"access":"none"},{"title":"Mark matched invoices ready to pay","detail":"Mismatches go to finance with the difference.","capability":"accounting","access":"write"}]'::jsonb, '{"name":"Supplier reconciliation","description":"Checks supplier invoices against bookings before payment.","autonomyLevel":3,"instructions":{"objective":"Only correct supplier invoices get paid.","context":"Finance pays; the agent only checks.","rules":["Never pay an invoice","Never change invoice amounts"],"steps":["Read the supplier invoice: Lines, amounts and references.","Find the matching bookings or orders: By reference and date.","Compare amounts and quantities: Flag any difference above the tolerance.","Mark matched invoices ready to pay: Mismatches go to finance with the difference."],"escalationConditions":["The difference is above the tolerance","The supplier is new"],"successConditions":["Every invoice matched or flagged"]},"successCriteria":["Every invoice matched or flagged"]}'::jsonb, 15, 'published'),
  ('library-viewing-scheduling', 'Viewing scheduling', 'Answers viewing requests, offers open slots and confirms viewings in the agent''s calendar.', 'Sales', array['Property & rentals']::text[], array['email', 'calendar']::text[], 'Someone asks to view a property', '[{"title":"Read the viewing request","detail":"Which property and when.","capability":"email","access":"read"},{"title":"Check open viewing slots","detail":"In the agent''s calendar.","capability":"calendar","access":"read"},{"title":"Offer two or three slots","detail":"With the address and what to bring.","capability":"email","access":"write"},{"title":"Book the chosen slot","detail":"And send a reminder the day before.","capability":"calendar","access":"write"}]'::jsonb, '{"name":"Viewing scheduling","description":"Books property viewings without back-and-forth.","autonomyLevel":4,"instructions":{"objective":"Every viewing request gets slots within the hour.","context":"Slots come from the agent''s calendar.","rules":["Never double-book","Never confirm a property is still available without checking"],"steps":["Read the viewing request: Which property and when.","Check open viewing slots: In the agent''s calendar.","Offer two or three slots: With the address and what to bring.","Book the chosen slot: And send a reminder the day before."],"escalationConditions":["The property is under offer"],"successConditions":["Slots offered","Chosen viewing booked"]},"successCriteria":["Slots offered","Chosen viewing booked"]}'::jsonb, 8, 'published'),
  ('library-maintenance-requests', 'Tenant maintenance requests', 'Logs each maintenance request, sets its urgency and books the right contractor.', 'Operations', array['Property & rentals']::text[], array['helpdesk', 'projects', 'email']::text[], 'A tenant reports a problem', '[{"title":"Read the request","detail":"Property, problem and photos.","capability":"helpdesk","access":"read"},{"title":"Set the urgency","detail":"Emergency (water, gas, no heat), urgent, or routine.","capability":null,"access":"none"},{"title":"Create the job","detail":"With urgency and access details.","capability":"projects","access":"write"},{"title":"Ask the right contractor for a slot","detail":"From the contractor list.","capability":"email","access":"write"},{"title":"Tell the tenant what happens next","detail":"And when.","capability":"helpdesk","access":"write"}]'::jsonb, '{"name":"Maintenance requests","description":"Turns maintenance requests into booked jobs.","autonomyLevel":3,"instructions":{"objective":"Tenants know within an hour what is being done.","context":"Contractors and their trades come from the contractor list.","rules":["Never approve costs above the repair limit"],"steps":["Read the request: Property, problem and photos.","Set the urgency: Emergency (water, gas, no heat), urgent, or routine.","Create the job: With urgency and access details.","Ask the right contractor for a slot: From the contractor list.","Tell the tenant what happens next: And when."],"escalationConditions":["Any emergency such as a leak, gas smell or no heating","The quote is above the repair limit"],"successConditions":["Job created","Contractor asked","Tenant told"]},"successCriteria":["Job created","Contractor asked","Tenant told"]}'::jsonb, 12, 'published'),
  ('library-rent-arrears', 'Rent arrears reminders', 'Reminds tenants about late rent on a set schedule and flags arrears to the property manager.', 'Finance', array['Property & rentals']::text[], array['accounting', 'payments', 'email', 'chat']::text[], 'Rent is three days late', '[{"title":"Find late rent payments","detail":"Tenant, property and amount.","capability":"accounting","access":"read"},{"title":"Check for a payment just received","detail":"Avoid reminding someone who has paid.","capability":"payments","access":"read"},{"title":"Send the reminder","detail":"Polite, with the amount and how to pay.","capability":"email","access":"write"},{"title":"Flag arrears over 14 days","detail":"To the property manager.","capability":"chat","access":"write"}]'::jsonb, '{"name":"Rent reminders","description":"Sends late-rent reminders and flags arrears.","autonomyLevel":3,"instructions":{"objective":"Late rent is paid without awkward chasing.","context":"Next steps beyond reminders are decided by the property manager.","rules":["Never mention eviction or legal steps","One reminder per week"],"steps":["Find late rent payments: Tenant, property and amount.","Check for a payment just received: Avoid reminding someone who has paid.","Send the reminder: Polite, with the amount and how to pay.","Flag arrears over 14 days: To the property manager."],"escalationConditions":["The tenant reports hardship","Arrears exceed one month''s rent"],"successConditions":["Reminders sent","Long arrears flagged"]},"successCriteria":["Reminders sent","Long arrears flagged"]}'::jsonb, 10, 'published'),
  ('library-claims-intake', 'Claims intake triage', 'Checks new claims are complete, routes them to the right handler, and requests what is missing. It never decides a claim.', 'Operations', array['Fintech & insurance']::text[], array['forms', 'email', 'helpdesk']::text[], 'A new claim is submitted', '[{"title":"Read the new claim","detail":"Policy, incident and attachments.","capability":"forms","access":"read"},{"title":"Check the claim is complete","detail":"Required fields and documents for this claim type.","capability":null,"access":"none"},{"title":"Request missing information","detail":"Exactly what is missing and why.","capability":"email","access":"write"},{"title":"Route complete claims to a handler","detail":"By claim type and value.","capability":"helpdesk","access":"write"}]'::jsonb, '{"name":"Claims intake","description":"Makes sure claims arrive complete with the right handler.","autonomyLevel":3,"instructions":{"objective":"Handlers only receive complete claims, routed correctly.","context":"Back-office only: handlers decide every claim.","rules":["Never accept, reject or value a claim","Never comment on cover"],"steps":["Read the new claim: Policy, incident and attachments.","Check the claim is complete: Required fields and documents for this claim type.","Request missing information: Exactly what is missing and why.","Route complete claims to a handler: By claim type and value."],"escalationConditions":["Fraud indicators","The claimant is vulnerable or distressed"],"successConditions":["Complete claims routed","Missing items requested"]},"successCriteria":["Complete claims routed","Missing items requested"]}'::jsonb, 15, 'published'),
  ('library-verification-follow-up', 'Account verification follow-up', 'Follows up customers whose account verification is stuck and tells compliance which files need review.', 'Operations', array['Fintech & insurance']::text[], array['crm', 'email', 'documents', 'chat']::text[], 'A verification has been pending for two days', '[{"title":"Find verifications stuck in pending","detail":"And what is missing.","capability":"crm","access":"read"},{"title":"Remind the customer","detail":"What to upload and how.","capability":"email","access":"write"},{"title":"Check what came back","detail":"Documents now provided.","capability":"documents","access":"read"},{"title":"Send complete files to compliance","detail":"For review; the agent never approves.","capability":"chat","access":"write"}]'::jsonb, '{"name":"Verification follow-up","description":"Unblocks stuck account verifications.","autonomyLevel":3,"instructions":{"objective":"Verifications are complete within a week.","context":"Back-office only: compliance approves every verification.","rules":["Never approve or reject a verification","Never ask for data the checklist does not require"],"steps":["Find verifications stuck in pending: And what is missing.","Remind the customer: What to upload and how.","Check what came back: Documents now provided.","Send complete files to compliance: For review; the agent never approves."],"escalationConditions":["Documents look inconsistent","The customer appears on a watch list"],"successConditions":["Reminders sent","Complete files with compliance"]},"successCriteria":["Reminders sent","Complete files with compliance"]}'::jsonb, 10, 'published'),
  ('library-client-intake', 'Client intake and engagement letter', 'Collects a new client''s details, prepares the engagement letter for signing, and opens the client file.', 'Operations', array['Professional services']::text[], array['crm', 'documents', 'esign']::text[], 'A new client is accepted', '[{"title":"Read the new client details","detail":"Contact, entity and the work agreed.","capability":"crm","access":"read"},{"title":"Prepare the engagement letter","detail":"From the standard template and the agreed scope.","capability":"documents","access":"write"},{"title":"Send it for signature","detail":"To the client contact.","capability":"esign","access":"write"},{"title":"Open the client file","detail":"With the signed letter once it is back.","capability":"documents","access":"write"}]'::jsonb, '{"name":"Client intake","description":"Gets new clients signed and filed.","autonomyLevel":2,"instructions":{"objective":"New clients are engaged properly within a day.","context":"Back-office only: a partner checks every letter before it is sent.","rules":["Never change fees or scope in the template","Never give advice"],"steps":["Read the new client details: Contact, entity and the work agreed.","Prepare the engagement letter: From the standard template and the agreed scope.","Send it for signature: To the client contact.","Open the client file: With the signed letter once it is back."],"escalationConditions":["The client is in a sector that needs extra checks"],"successConditions":["Letter prepared and sent","Client file opened"]},"successCriteria":["Letter prepared and sent","Client file opened"]}'::jsonb, 25, 'published')
